+interface Address {
+  street: string;
+  city: string;
+  state: string;
+  zipCode: string;
+  country: string;
+}
+
+interface UserProfile {
+  id: string;
+  name: string;
+  email: string;
+  address: Address | null;
+  phone: string | null;
+  createdAt: string;
+}
+
+interface ProfileSummary {
+  displayName: string;
+  email: string;
+  location: string;
+  memberSince: string;
+}
+
+async function fetchUserProfile(userId: string): Promise<UserProfile> {
+  var response = await fetch("/api/users/" + userId);
+  if (!response.ok) {
+    throw new Error("Failed to fetch user profile: " + response.status);
+  }
+  return response.json();
+}
+
+export async function getProfileSummary(userId: string): Promise<ProfileSummary> {
+  var profile = await fetchUserProfile(userId);
+
+  var createdDate = new Date(profile.createdAt);
+  var formattedDate = createdDate.toLocaleDateString("en-US", {
+    year: "numeric",
+    month: "long",
+  });
+
+  var locationParts = [profile.address.city, profile.address.state];
+  var location = locationParts.filter(Boolean).join(", ");
+
+  return {
+    displayName: profile.name,
+    email: profile.email,
+    location: location || "Not specified",
+    memberSince: formattedDate,
+  };
+}
